use op15_adaptive_harness::{Budget, BudgetUse, Controller, Decision, Evidence, EvidenceSet, StopReason, Task};
#[test] fn confidence_cannot_bypass_evidence() { let d = Controller::decide(&Task { id: "t".into(), claim: "claim".into(), tool_available: true, confidence_milli: 999 }, &EvidenceSet::default(), Budget { wall_ms: 10, tokens: 10, ram_mb: 10, tool_calls: 1 }, BudgetUse { wall_ms: 1, tokens: 1, ram_mb: 1, tool_calls: 1 }); assert_ne!(d, Decision::Answer); }
#[test] fn independent_fresh_evidence_allows_answer() { let e = Evidence { id: "oracle".into(), provenance: "test".into(), supports_claim: "claim".into(), independently_verified: true, stale: false }; let d = Controller::decide(&Task { id: "t".into(), claim: "claim".into(), tool_available: false, confidence_milli: 0 }, &EvidenceSet(vec![e]), Budget { wall_ms: 0, tokens: 0, ram_mb: 0, tool_calls: 0 }, BudgetUse::default()); assert_eq!(d, Decision::Answer); }
#[test] fn abstains_when_low_confidence_and_no_evidence() { let d = Controller::decide(&Task { id: "t".into(), claim: "claim".into(), tool_available: true, confidence_milli: 1 }, &EvidenceSet::default(), Budget { wall_ms: 10, tokens: 10, ram_mb: 10, tool_calls: 1 }, BudgetUse { wall_ms: 1, tokens: 1, ram_mb: 1, tool_calls: 1 }); assert_eq!(d, Decision::Stop(StopReason::Abstain)); }
